source='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    groups = []
    r = 0
    while r < h:
        if all(v == background for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != background for v in grid[r]):
            r += 1
        groups.append((start, r))

    for i, (a0, a1) in enumerate(groups):
        for b0, b1 in groups[i + 1:]:
            if a1 - a0 != b1 - b0:
                continue
            for off in range(a1 - a0):
                ra, rb = grid[a0 + off], grid[b0 + off]
                start = w
                side = None
                while start > 0:
                    x, y = ra[start - 1], rb[start - 1]
                    if x == background and y != background:
                        if side not in (None, 0):
                            break
                        side = 0
                        start -= 1
                    elif y == background and x != background:
                        if side not in (None, 1):
                            break
                        side = 1
                        start -= 1
                    else:
                        break
                if side == 0:
                    for c in range(start, w):
                        if grid[a0 + off][c] == background:
                            out[a0 + off][c] = 1
                elif side == 1:
                    for c in range(start, w):
                        if grid[b0 + off][c] == background:
                            out[b0 + off][c] = 1
    return out
